with recent_stores as (select * from stores where city not in ('Berlin', 'Chiang Mai')), agg as (select date_format(opened_date, 'yyyy-MM') as opened_month, round((100 * sum(case when city = 'Tokyo' then 1 else 0 end)) / count(*), 1) as pct_tokyo, max(opened_date) as last_opened_date from recent_stores group by date_format(opened_date, 'yyyy-MM')) select * from agg order by last_opened_date desc, opened_month desc limit 20
